opener(2, 'תרגילים מסכמים למפגש 2', 'שאלת החלק: האם אתם יודעים לבנות את החישוב לבד?',
       ['שני תרגילי חישוב: Long Put ו-Short Call', 'שלושה תרגילים בגיליון Excel שבתוך השקף', 'בכל תרגיל: הנתונים בטבלה, הנוסחאות גלויות, רמז, פתרון חלקי ופתרון מלא'], 30,
       note='<b>מה כבר תרגלנו:</b> כל פוזיציה לחוד, בהדרגה. <b>כאן:</b> אותו חישוב, מהתחלה ועד הסוף, בלי ליווי צמוד.')

_E_SOLVE('t-1', 'תרגיל 1: Long Put', 'תרגיל 1: קונה אופציית מכר (Long Put)',
         'משקיע מחזיק מניה שנסחרת היום ב-85 ש״ח, וחושש שמחירה ירד בשלושת החודשים הקרובים. כדי להגן על עצמו, הוא קונה אופציית מכר (Put) על מניה אחת, כלומר במכפיל (Multiplier) 1. מחיר המימוש (K) הוא 80 ש״ח, והפרמיה (p) שהוא משלם היום היא 5 ש״ח. <b>נדרש:</b> ענו על ארבעת הסעיפים, בשקלים למניה אחת.',
         [('א. מה יהיה הרווח של המשקיע מהאופציה, אם מחיר המניה בפקיעה יהיה 72 ש״ח?', 3, 0.001),
          ('ב. באיזה מחיר מניה בפקיעה הוא לא ירוויח ולא יפסיד, כלומר מהי נקודת האיזון (Break-even)?', 75, 0.001),
          ('ג. באיזה מחיר מניה בפקיעה הרווח שלו יהיה בדיוק 12 ש״ח?', 63, 0.001),
          ('ד. מהו הרווח המרבי שהמשקיע יכול להשיג מהאופציה?', 75, 0.001)],
         ['התזרים של Put בפקיעה: $max(K − S_{T}, 0)$. הרווח הוא התזרים פחות הפרמיה $p$.', 'בנקודת האיזון הרווח אפס: $K − S_{T} − p = 0$. חלצו את $S_{T}$.', 'הרווח המרבי מתקבל כשמחיר המניה יורד עד אפס.'],
         '<b>רווח של Long Put</b> = $max(K − S_{T}, 0) − p$. באקסל: הפונקציה MAX, ובתוכה מחיר המימוש פחות המחיר בפקיעה, ואפס.<br><b>נקודת איזון</b> = $K − p$. <b>רווח מרבי</b> = $K − p$, כשהמניה יורדת לאפס.',
         [('הרווח במחיר 72', '$max(K − S_{T}, 0) − p$', 'max(80 − 72, 0) − 5', '3 ש״ח'),
          ('נקודת האיזון', 'רווח אפס: $S_{T} = K − p$', '80 − 5', '75 ש״ח'),
          ('המחיר לרווח 12', '$K − S_{T} − p = 12$, ולכן $S_{T} = K − p − 12$', '80 − 5 − 12', '63 ש״ח'),
          ('הרווח המרבי', 'המניה ב-0: $K − 0 − p$', '80 − 0 − 5', '75 ש״ח')],
         [('מחיר המניה היום ($S$)', '85 ש״ח'), ('מחיר מימוש ($K$)', '80 ש״ח'), ('פרמיה ($p$)', '5 ש״ח'), ('מכפיל (Multiplier)', '1, מניה אחת')])

_E_SOLVE('t-2', 'תרגיל 2: Short Call', 'תרגיל 2: כותבת אופציית רכש (Short Call)',
         'משקיעה מעריכה שמניה, שנסחרת היום ב-58 ש״ח, לא תעלה הרבה בשלושת החודשים הקרובים. לכן היא כותבת (מוכרת) אופציית רכש (Call) על מניה אחת, ומקבלת היום פרמיה (c) של 4 ש״ח. מחיר המימוש (K) הוא 60 ש״ח: אם הקונה יממש, היא חייבת למכור לו את המניה ב-60 ש״ח. <b>נדרש:</b> ענו על ארבעת הסעיפים, בשקלים למניה אחת.',
         [('א. מה יהיה הרווח או ההפסד שלה, אם מחיר המניה בפקיעה יהיה 70 ש״ח?', -6, 0.001),
          ('ב. מה יהיה הרווח או ההפסד שלה, אם מחיר המניה בפקיעה יהיה 55 ש״ח?', 4, 0.001),
          ('ג. באיזה מחיר מניה בפקיעה היא לא תרוויח ולא תפסיד, כלומר מהי נקודת האיזון?', 64, 0.001),
          ('ד. מהו הרווח המרבי שהיא יכולה להשיג מהאופציה?', 4, 0.001)],
         ['הכותבת מקבלת את הפרמיה $c$ בכל מקרה.', 'אם הקונה מממש, היא מוכרת ב-$K$ מניה ששווה $S_{T}$, ומפסידה $S_{T} − K$.', 'במחיר 55 הקונה לא מממש: למה לקנות ב-60 מניה שאפשר לקנות בשוק ב-55?'],
         '<b>רווח של Short Call</b> = $c − max(S_{T} − K, 0)$. באקסל: הפרמיה פחות MAX, ובתוכה המחיר בפקיעה פחות מחיר המימוש, ואפס.<br><b>נקודת איזון</b> = $K + c$. <b>רווח מרבי</b> = הפרמיה $c$, כשהקונה לא מממש.',
         [('הרווח במחיר 70', '$c − max(S_{T} − K, 0)$', '4 − max(70 − 60, 0)', 'הפסד, $−6$ ש״ח'),
          ('הרווח במחיר 55', '$c − max(S_{T} − K, 0)$', '4 − max(55 − 60, 0)', '4 ש״ח'),
          ('נקודת האיזון', 'רווח אפס: $S_{T} = K + c$', '60 + 4', '64 ש״ח'),
          ('הרווח המרבי', 'הקונה לא מממש: $c − 0$', '4 − 0', '4 ש״ח')],
         [('מחיר המניה היום ($S$)', '58 ש״ח'), ('מחיר מימוש ($K$)', '60 ש״ח'), ('פרמיה שהתקבלה ($c$)', '4 ש״ח'), ('מכפיל (Multiplier)', '1, מניה אחת')])

OPTX('e-1', 'תרגיל 3: Long Call באקסל', 'משקיע מעריך שמניה, שנסחרת היום ב-100 ש״ח, תעלה בחודשים הקרובים. לכן הוא קונה אופציית רכש (Call) על מניה אחת. מחיר המימוש (K) הוא 105 ש״ח, והפרמיה (c) שהוא משלם היום היא 4 ש״ח. <b>נדרש:</b> השלימו בטבלה את התזרים בפקיעה ואת הרווח או ההפסד, כשמחיר המניה בפקיעה נע בין 85 ל-125 ש״ח. כתבו נוסחה בשורה הראשונה, וגררו אותה למטה.', 105, 4, 'call', 1, [85, 95, 105, 115, 125], False, -10, 25, [-10, 0, 10, 20], [85, 95, 105, 115, 125])
