OPTX('e-3', 'תרגיל 5: Short Call באקסל', 'קרן השקעות מחזיקה מניות שנסחרות היום ב-72 ש״ח, ומוכנה למכור אותן ב-75 ש״ח. לכן היא כותבת (מוכרת) אופציית רכש (Call) על המניה, ומקבלת היום פרמיה (c) של 5 ש״ח. מחיר המימוש (K) הוא 75 ש״ח: אם הקונה יממש, הקרן חייבת למכור לו את המניה ב-75 ש״ח. <b>נדרש:</b> השלימו בטבלה את התזרים בפקיעה ואת הרווח או ההפסד של הקרן מהאופציה בלבד, כשמחיר המניה בפקיעה נע בין 60 ל-90 ש״ח.', 75, 5, 'call', -1, [60, 70, 75, 80, 90], False, -15, 10, [-15, -10, -5, 0, 5, 10], [60, 70, 75, 80, 90])


_SUM = ['אופציה (Option) היא זכות בלי חובה. הקונה (Long) משלם היום פרמיה (Premium), והכותב (Short) מקבל אותה ומתחייב.',
        'אופציית רכש (Call) נותנת זכות לקנות במחיר המימוש (K). אופציית מכר (Put) נותנת זכות למכור ב-K.',
        'קודם מחשבים תזרים בפקיעה (Payoff), בלי הפרמיה. אחר כך רווח (P&L): פחות הפרמיה אצל הקונה, ועוד הפרמיה אצל הכותב.',
        'נקודת האיזון (Break-even): ב-Call היא $K + c$, ב-Put היא $K − p$. היא זהה לקונה ולכותב.',
        'הקונה מפסיד לכל היותר את הפרמיה. כותב Call חשוף להפסד בלי תקרה, ולכן נדרש להפקיד ביטחונות.',
        'הקונה והכותב הם תמונת ראי: מה שאחד מרוויח, השני מפסיד.']
S('s-sum', 'סיכום השיעור', 'סיכום המפגש: שישה משפטים, וטבלת נוסחאות אחת',
  '<ol class="steps two">' + ''.join(ST(i + 1, f'<span>{TX(x)}</span>', 'li') for i, x in enumerate(_SUM)) + '</ol>'
  + ST(7, '<table class="tbl2 e-fs"><tr><th>הנוסחאות של המפגש</th><th>קונה Call (Long Call)</th><th>כותב Call (Short Call)</th><th>קונה Put (Long Put)</th><th>כותב Put (Short Put)</th></tr>'
       + '<tr><td>' + TX('<b>תזרים (Payoff)</b>') + '</td>' + ''.join(f'<td>{TX(x)}</td>' for x in ['$max(S_{T} − K, 0)$', '$−max(S_{T} − K, 0)$', '$max(K − S_{T}, 0)$', '$−max(K − S_{T}, 0)$']) + '</tr>'
       + '<tr><td>' + TX('<b>רווח (P&L)</b>') + '</td>' + ''.join(f'<td>{TX(x)}</td>' for x in ['Payoff − c', 'Payoff + c', 'Payoff − p', 'Payoff + p']) + '</tr>'
       + '<tr><td>' + TX('<b>נקודת איזון (Break-even)</b>') + '</td>' + ''.join(f'<td>{TX(x)}</td>' for x in ['$K + c$', '$K + c$', '$K − p$', '$K − p$']) + '</tr></table>')
  + BAND('dg', 'במפגש הבא: חוזה אחד מתייחס להרבה יחידות. נכפול את כל הטבלה הזו במכפיל (Multiplier), ונעבור מיחידה אחת לשקלים.', 8),
  kick='סיכום')

