def _D2_DISC(sid, title, story, ask, steps, extra='', meme=None):
    """A discussion question: the full story, what is asked, a prompt to write first, and a model answer revealed point by point."""
    body = (f'<div class="row eq2 top"><div class="col"><div class="card qstem"><p>{TX(story)}</p><p>{TX("<b>נדרש:</b> " + ask)}</p></div>'
            + '<div class="band note">' + TX('<b>לפני שפותחים:</b> כתבו תשובה של שלוש שורות. אחר כך השוו לתשובה לדוגמה, נקודה אחר נקודה.') + '</div>' + extra
            + (meme or '') + '</div><div class="card rl"><b class="ct">תשובה לדוגמה</b>' + RL(steps) + '</div></div>')
    S(sid, title, title, body, kick=f'חלק {CUR[0]} · שאלת דיון')


